bool common_subproc::create(
        const std::vector<std::string> & args,
        int options,
        const std::vector<std::string> & env,
        const char * cwd) {
    auto argv = to_cstr_vec(args);

    int result;
    if (env.empty() && cwd == nullptr) {
        result = subprocess_create(argv.data(), options, &proc);
    } else {
        auto envp = to_cstr_vec(env);
        result = subprocess_create_ex(argv.data(), options, env.empty() ? nullptr : envp.data(), cwd, &proc);
    }

    is_created = result == 0;

#if !defined(_WIN32)
    // subprocess_create() never calls setpgid, so this child stays in our own
    // process group. terminate() below can then only SIGKILL this one pid: any
    // grandchild it spawns and keeps alive (server-tools.cpp's tools-runtime
    // container process, respawned if it dies) is reparented to init on kill
    // and outlives it, invisible to anything matching on our own argv. Putting
    // the child in its own group here means terminate() can kill that whole
    // group instead of just the one pid.
    if (is_created && proc.child > 0) {
        setpgid(proc.child, proc.child);
    }
#endif

    return is_created;
}

