# a role="tool" message, immediately after the assistant tool_calls
# message THINK already appended, so the next breath cycle's THINK
# sees it. Plain-text MTOOL:/TOOL:/TOKEN: lines are still honored too,
# in case a model answers in that form instead of (or alongside) a
# real tool_call.
def _act(self, thought):
    content = thought.get("content", "")
    results = []
    for tc in thought.get("tool_calls") or []:
        name = tc.get("function", {}).get("name", "")
        raw_args = tc.get("function", {}).get("arguments", "") or "{}"
        try:
            args = json.loads(raw_args)
        except json.JSONDecodeError:
            args = {}
        result = self._run_tool_call(name, args)
        results.append(f"{name}({raw_args}) => {result}")
        self.conversation.append({"role": "tool", "tool_call_id": tc.get("id", ""),
                                   "content": result[:2000]})
    for line in content.split("\n"):
        line = line.strip()
        if not line:
            continue
        if line.startswith("TOKEN:") or line.startswith("COMPOSE:") or line.startswith("CANONICAL:"):
            results.append(self._handle_token_command(line))
        elif line.startswith("MTOOL:"):
            results.append(self._handle_mtool(line))
        elif line.startswith("TOOL:") or line.startswith("ACTION:"):
            results.append(self._handle_ig_tool(line))
    if results:
        action_content = "; ".join(results)
        self.crystal.commit(CrystalRecord(
            address=self.cycle_count * 100 + 2,
            tuple_hash=hashlib.sha256(action_content.encode()).hexdigest()[:16],
            belnap_state=B4.T,
            timestamp=time.time(),
            program_counter=self.kernel.ip,
            tick=self.kernel.tick_count,
            content=action_content,
            content_type="action",
        ))
        self.memory.append(("action", B4.T, action_content))
        return {"type": "tool_call", "calls": results, "verdict": "T",
                "content": action_content}
    return {"type": "text_response", "verdict": thought.get("verdict", "N")}

def _handle_mtool(self, line: str) -> str:
    """Ground an `MTOOL:` line through the live mOMonadOS kernel REPL."""
    cmd = line[len("MTOOL:"):].strip()
    if not cmd:
        return "MTOOL: (empty — usage MTOOL: ig <name> | cycle <word> | ...)"
    try:
        r = momos_bridge.run(cmd)
    except Exception as exc:
        return f"MTOOL: {cmd}  => [momos bridge error: {exc}]"
    return f"MTOOL: {cmd}  => [{r['status']}] {r['output'][:800]}"

def _handle_ig_tool(self, line: str) -> str:
    """Ground a `TOOL:`/`ACTION:` line through the live IG dispatcher."""
