//! dialetheic_llm — a transformer whose attention and feed-forward blocks
//! never collapse T and F into one number before they've been held.
//!
//! Source: `ob3ect/digital/dialetheic_paraconsistent_native_llm
//! /dialetheic_paraconsistent_native_llm_ob3ect.json`, `phases.phase_4.steps`.
//! That sequence is not a description of a transformer, it is a build order:
//! `∈` split heads, `⊤` affirm arm, `⊥` reject arm, `⊞` HOLD both, `∋` fuse.
//! A standard transformer computes `⊤` and `⊥` as one step — masked softmax
//! sends the disallowed (future) logits to -inf before the softmax even
//! runs, so the "reject" information never exists as a value anywhere. This
//! model computes both arms as real tensors, concatenates them (the `⊞`
//! hold), and only reduces dimension afterward through a learned projection
//! (the `∋` fuse) — so what to do with the contradiction is learned, not
//! erased by the architecture in advance.
//!
//! The feed-forward block repeats the same shape as a two-expert version:
//! an affirm expert and a reject expert are BOTH always evaluated (no
//! top-1 routing, which would discard one arm the way masked softmax
//! discards the future), and a learned gate blends them per token.

use candle_core::{DType, Device, Result, Tensor, D};
use candle_nn::{
    embedding, layer_norm, linear, Embedding, LayerNorm, LayerNormConfig, Linear, Module,
    VarBuilder,
};

/// The twelve marks, in kernel slot order. `id_of`/`glyph_of` are the whole
/// vocabulary — this is a from-scratch build, so it does not reach into
/// imasm_core or vita_native for the alphabet.
pub const GLYPHS: [char; 12] = [
    '⊢', '⊣', '≻', '≺', '⋈', '⊤', '∈', '∋', '⊙', '⊥', '⊞', '◻',
];
pub const VOCAB_SIZE: usize = GLYPHS.len();

pub fn id_of(c: char) -> Option<usize> {
    GLYPHS.iter().position(|&g| g == c)
}

pub fn glyph_of(id: usize) -> char {
    GLYPHS[id]
}

pub fn encode(word: &str) -> Vec<usize> {
    word.chars().filter_map(id_of).collect()
}

pub fn decode(ids: &[usize]) -> String {
    ids.iter().map(|&i| glyph_of(i)).collect()
}

#[derive(Clone, Copy, Debug)]
pub struct Config {
    pub d_model: usize,
    pub n_head: usize,
    pub d_ff: usize,
    pub n_layer: usize,
    pub max_len: usize,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            d_model: 64,
            n_head: 4,
            d_ff: 256,
            n_layer: 4,
            max_len: 128,
        }
    }
}

/// The `∈ ⊤ ⊥ ⊞ ∋` shape applied to attention. Affirm is ordinary causal
/// softmax attention. Reject is softmax attention over exactly the positions
/// affirm was forbidden from seeing — the future — so it is a real signal,
/// not affirm's mirror image. Both are concatenated (held) per head before
/// the output projection fuses them down to d_model.
pub struct DialetheicAttention {
    q: Linear,
    k: Linear,
    v: Linear,
    o: Linear,
    n_head: usize,
    d_head: usize,
}

impl DialetheicAttention {
    pub fn new(d_model: usize, n_head: usize, vb: VarBuilder) -> Result<Self> {
        assert_eq!(d_model % n_head, 0, "d_model must divide evenly into n_head");
        let d_head = d_model / n_head;
        Ok(Self {
            q: linear(d_model, d_model, vb.pp("q"))?,
            k: linear(d_model, d_model, vb.pp("k"))?,
            v: linear(d_model, d_model, vb.pp("v"))?,
            // held width is 2*d_model (affirm ++ reject, per head, concatenated
            // back together across heads), fused down to d_model here.
            o: linear(2 * d_model, d_model, vb.pp("o"))?,
            n_head,
            d_head,
        })
    }

    /// x: (batch, seq, d_model). Returns (batch, seq, d_model).
    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let (b, n, _) = x.dims3()?;
        let h = self.n_head;
        let dh = self.d_head;
        let dev = x.device();

        let split_heads = |t: &Tensor| -> Result<Tensor> {
            t.reshape((b, n, h, dh))?.transpose(1, 2)?.contiguous() // (b,h,n,dh)
        };
        let q = split_heads(&self.q.forward(x)?)?;
        let k = split_heads(&self.k.forward(x)?)?;
        let v = split_heads(&self.v.forward(x)?)?;

        let scale = 1f64 / (dh as f64).sqrt();
        let scores = (q.matmul(&k.transpose(D::Minus2, D::Minus1)?)? * scale)?; // (b,h,n,n)

        // allowed[i][j] = 1 if j<=i (causal), 0 otherwise. neg_inf on the
        // opposite side gives affirm (causal) and reject (anti-causal, i.e.
        // the future) as two genuinely different softmax distributions.
        let mut allow = vec![0f32; n * n];
        let mut deny = vec![0f32; n * n];
        for i in 0..n {
            for j in 0..n {
                if j <= i {
                    allow[i * n + j] = 0.0;
                    deny[i * n + j] = f32::NEG_INFINITY;
                } else {
                    allow[i * n + j] = f32::NEG_INFINITY;
                    deny[i * n + j] = 0.0;
                }
            }
        }
        let allow_mask = Tensor::from_vec(allow, (1, 1, n, n), dev)?.to_dtype(scores.dtype())?;
        let deny_mask = Tensor::from_vec(deny, (1, 1, n, n), dev)?.to_dtype(scores.dtype())?;

        let affirm_logits = scores.broadcast_add(&allow_mask)?;
        let reject_logits = scores.broadcast_add(&deny_mask)?;

        let affirm = candle_nn::ops::softmax(&affirm_logits, D::Minus1)?;
        // row i=n-1 has no future: every entry of reject_logits[n-1] is
        // -inf, softmax would be NaN. Zero that row's weights explicitly --
        // an empty reject arm is a real value (nothing to hold), not a
        // numerical accident.
        let reject_raw = candle_nn::ops::softmax(&reject_logits, D::Minus1)?;
        let mut row_has_future = vec![1f32; n];
        row_has_future[n - 1] = 0.0;
        let row_mask = Tensor::from_vec(row_has_future, (1, 1, n, 1), dev)?
            .to_dtype(reject_raw.dtype())?;
        let reject = reject_raw.broadcast_mul(&row_mask)?;

        let affirm_out = affirm.matmul(&v)?; // (b,h,n,dh)
        let reject_out = reject.matmul(&v)?; // (b,h,n,dh)

        // HOLD: concat affirm and reject per head, then concat heads.
        let held = Tensor::cat(&[&affirm_out, &reject_out], D::Minus1)?; // (b,h,n,2dh)
        let held = held.transpose(1, 2)?.contiguous()?.reshape((b, n, h * 2 * dh))?;

        // FUSE: one learned projection back to d_model.
        self.o.forward(&held)
    }
}

/// The `∈ ⊤ ⊥ ⊞ ∋` shape applied to the feed-forward block: an affirm
/// expert and a reject expert are both always evaluated (never top-1
/// routed — routing would re-introduce the same collapse this whole model
/// is built to avoid), and a learned per-token gate blends the two without
/// ever letting either weight reach exactly zero.
pub struct DialetheicFfn {
    affirm_in: Linear,
    affirm_out: Linear,
    reject_in: Linear,
    reject_out: Linear,
    gate: Linear,
}

impl DialetheicFfn {
    pub fn new(d_model: usize, d_ff: usize, vb: VarBuilder) -> Result<Self> {
        Ok(Self {
            affirm_in: linear(d_model, d_ff, vb.pp("affirm_in"))?,
            affirm_out: linear(d_ff, d_model, vb.pp("affirm_out"))?,
            reject_in: linear(d_model, d_ff, vb.pp("reject_in"))?,
            reject_out: linear(d_ff, d_model, vb.pp("reject_out"))?,
            gate: linear(d_model, 1, vb.pp("gate"))?,
        })
    }

    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let affirm = self.affirm_out.forward(&self.affirm_in.forward(x)?.gelu()?)?;
        let reject = self.reject_out.forward(&self.reject_in.forward(x)?.gelu()?)?;
        // sigmoid gate in (0,1): both arms always contribute something,
        // matching "coexist without collapse" rather than a hard switch.
        let g = candle_nn::ops::sigmoid(&self.gate.forward(x)?)?; // (b,n,1)
        let one_minus_g = (1.0 - &g)?;
        affirm.broadcast_mul(&g)? + reject.broadcast_mul(&one_minus_g)?
    }
}

pub struct Block {
    ln1: LayerNorm,
    attn: DialetheicAttention,
    ln2: LayerNorm,
    ffn: DialetheicFfn,
}

impl Block {
    pub fn new(cfg: &Config, vb: VarBuilder) -> Result<Self> {
        let lncfg = LayerNormConfig::default();
        Ok(Self {
            ln1: layer_norm(cfg.d_model, lncfg, vb.pp("ln1"))?,
            attn: DialetheicAttention::new(cfg.d_model, cfg.n_head, vb.pp("attn"))?,
            ln2: layer_norm(cfg.d_model, lncfg, vb.pp("ln2"))?,
            ffn: DialetheicFfn::new(cfg.d_model, cfg.d_ff, vb.pp("ffn"))?,
        })
    }

    /// `⋈` residual composition around both sub-blocks.
    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let x = (x + self.attn.forward(&self.ln1.forward(x)?)?)?;
        let x = (&x + self.ffn.forward(&self.ln2.forward(&x)?)?)?;
        Ok(x)
    }
}

pub struct DialetheicLlm {
    tok_emb: Embedding,
    pos_emb: Embedding,
    blocks: Vec<Block>,
    ln_f: LayerNorm,
    head: Linear,
    pub cfg: Config,
}

impl DialetheicLlm {
    pub fn new(cfg: Config, vb: VarBuilder) -> Result<Self> {
        let tok_emb = embedding(VOCAB_SIZE, cfg.d_model, vb.pp("tok_emb"))?;
        let pos_emb = embedding(cfg.max_len, cfg.d_model, vb.pp("pos_emb"))?;
        let mut blocks = Vec::with_capacity(cfg.n_layer);
        for i in 0..cfg.n_layer {
            blocks.push(Block::new(&cfg, vb.pp(format!("block{i}")))?);
        }
        let ln_f = layer_norm(cfg.d_model, LayerNormConfig::default(), vb.pp("ln_f"))?;
        let head = linear(cfg.d_model, VOCAB_SIZE, vb.pp("head"))?;
        Ok(Self {
            tok_emb,
            pos_emb,
            blocks,
            ln_f,
            head,
            cfg,
        })
    }

    /// ids: (batch, seq) of glyph ids. Returns logits (batch, seq, VOCAB_SIZE).
    pub fn forward(&self, ids: &Tensor) -> Result<Tensor> {
        let (b, n) = ids.dims2()?;
        let dev = ids.device();
        let pos = Tensor::arange(0u32, n as u32, dev)?
            .reshape((1, n))?
            .broadcast_as((b, n))?;
        let mut x = (self.tok_emb.forward(ids)? + self.pos_emb.forward(&pos)?)?;
        for blk in &self.blocks {
            x = blk.forward(&x)?;
        }
        let x = self.ln_f.forward(&x)?;
        self.head.forward(&x)
    }
}

pub fn device() -> Result<Device> {
    if candle_core::utils::cuda_is_available() {
        Device::new_cuda(0)
    } else {
        Ok(Device::Cpu)
    }
}

pub fn dtype() -> DType {
    DType::F32
}

