//! Steps 19-23 of the spec: backprop, chain the gradient through the
//! network, have the model recognize its own update (⊙ — made concrete
//! below as the printed per-step parameter-delta norm, not a metaphor),
//! hold the stability/adaptation tension (AdamW's own job), anchor the
//! final state (checkpoint save, ⊣).

use candle_core::{DType, Tensor};
use candle_nn::{AdamW, Optimizer, ParamsAdamW, VarBuilder, VarMap};
use dialetheic_llm::{device, encode, Config, DialetheicLlm};
use std::io::Read;

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let corpus_path = args
        .get(1)
        .cloned()
        .unwrap_or_else(|| "/home/mrnob0dy666/imsgct/daydr33m/m2_torus/ob3ect_words.txt".into());
    let steps: usize = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(2000);
    let out_path = args
        .get(3)
        .cloned()
        .unwrap_or_else(|| "/home/mrnob0dy666/imsgct/dialetheic_llm/dialetheic.safetensors".into());

    let mut raw = String::new();
    std::fs::File::open(&corpus_path)?.read_to_string(&mut raw)?;
    let words: Vec<Vec<usize>> = raw
        .lines()
        .map(|l| encode(l.trim()))
        .filter(|w| w.len() >= 2)
        .collect();
    if words.is_empty() {
        anyhow::bail!("no usable rings in {corpus_path} (need lines of the 12 glyphs, len>=2)");
    }
    println!("[corpus] {} rings from {corpus_path}", words.len());

    let cfg = Config::default();
    let dev = device()?;
    let varmap = VarMap::new();
    let vb = VarBuilder::from_varmap(&varmap, DType::F32, &dev);
    let model = DialetheicLlm::new(cfg, vb)?;

    let params = ParamsAdamW { lr: 3e-4, ..Default::default() };
    let mut opt = AdamW::new(varmap.all_vars(), params)?;

    let mut rng = rand::thread_rng();
    use rand::Rng;

    let mut prev_norm: Option<f64> = None;
    for step in 0..steps {
        let w = &words[rng.gen_range(0..words.len())];
        let n = w.len().min(cfg.max_len);
        let ids: Vec<u32> = w[..n].iter().map(|&x| x as u32).collect();
        if n < 2 {
            continue;
        }
        let input = Tensor::from_vec(ids[..n - 1].to_vec(), (1, n - 1), &dev)?;
        let target = Tensor::from_vec(ids[1..n].to_vec(), (1, n - 1), &dev)?;

        let logits = model.forward(&input)?; // (1, n-1, V)
        let logits = logits.reshape(((n - 1), dialetheic_llm::VOCAB_SIZE))?;
        let target = target.reshape((n - 1,))?;
        let loss = candle_nn::loss::cross_entropy(&logits, &target)?;

        opt.backward_step(&loss)?;

        if step % 100 == 0 || step + 1 == steps {
            // ⊙ self-modeling: the update the model just made, read back off
            // its own weights, not asserted.
            let mut sq = 0f64;
            for v in varmap.all_vars() {
                let t = v.as_tensor().to_dtype(DType::F32)?;
                let s: f64 = t.sqr()?.sum_all()?.to_scalar::<f32>()? as f64;
                sq += s;
            }
            let norm = sq.sqrt();
            let delta = prev_norm.map(|p| norm - p).unwrap_or(0.0);
            prev_norm = Some(norm);
            let loss_v: f32 = loss.to_scalar()?;
            println!(
                "step {step:6} loss {loss_v:.4}  |W|={norm:.4} d|W|={delta:+.4}"
            );
        }
    }

    varmap.save(&out_path)?;
    println!("[anchor] saved {out_path}");
    Ok(())
}

