//! Autoregressive sampling. This recomputes the full forward pass every
//! step rather than an incremental KV cache -- step 18 of the spec ("fix
//! the key-value pairs into the KV cache as a permanent record") is
//! correct but not yet built here; this is the honest, slower stand-in.

use candle_core::{DType, Tensor};
use candle_nn::{VarBuilder, VarMap};
use dialetheic_llm::{decode, device, encode, glyph_of, Config, DialetheicLlm, VOCAB_SIZE};
use rand::Rng;

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let ckpt = args
        .get(1)
        .cloned()
        .unwrap_or_else(|| "/home/mrnob0dy666/imsgct/dialetheic_llm/dialetheic.safetensors".into());
    let seed_word = args.get(2).cloned().unwrap_or_else(|| "⊢".into());
    let n_gen: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(40);

    let cfg = Config::default();
    let dev = device()?;
    let mut varmap = VarMap::new();
    let vb = VarBuilder::from_varmap(&varmap, DType::F32, &dev);
    let model = DialetheicLlm::new(cfg, vb)?;
    varmap.load(&ckpt)?;

    let mut ids = encode(&seed_word);
    if ids.is_empty() {
        anyhow::bail!("seed word must be built from the twelve glyphs");
    }
    let mut rng = rand::thread_rng();

    for _ in 0..n_gen {
        let n = ids.len().min(cfg.max_len);
        let window: Vec<u32> = ids[ids.len() - n..].iter().map(|&x| x as u32).collect();
        let input = Tensor::from_vec(window, (1, n), &dev)?;
        let logits = model.forward(&input)?; // (1, n, V)
        let last = logits.i((0, n - 1))?.to_dtype(DType::F32)?;
        let probs = candle_nn::ops::softmax(&last, 0)?;
        let probs: Vec<f32> = probs.to_vec1()?;

        let r: f32 = rng.gen();
        let mut acc = 0f32;
        let mut next = VOCAB_SIZE - 1;
        for (i, &p) in probs.iter().enumerate() {
            acc += p;
            if r <= acc {
                next = i;
                break;
            }
        }
        ids.push(next);
        if glyph_of(next) == '⊣' {
            break;
        }
    }

    println!("{}", decode(&ids));
    Ok(())
}

