1	//! m2-train — the toroidal trunk as a masked-ring IMASM denoiser, native and
2	//! Grammar-architected. Learns from structured rings (grammar-biased words over
3	//! the twelve marks); masks positions and predicts them from the ring's
4	//! neighbourhood through the circulant attention. Held-out denoising accuracy is
5	//! reported against the twelve-glyph alphabet, and a sample is scored by the
6	//! kernel's own verdict (`word_verdict`).
7	//!
8	//! Usage: m2-train [steps] [out.safetensors] [words.txt]
9	
10	use candle_core::{DType, Device, Result, Tensor};
11	use candle_nn::{AdamW, Optimizer, ParamsAdamW, VarBuilder, VarMap};
12	
13	use imasm_core::check::{word_verdict, ClosureState};
14	use imasm_core::classic::Token;
15	use m2_torus::config::Config;
16	use m2_torus::model::TorusTrunk;
17	use vita_native::alphabet;
18	
19	const GLYPHS: [&str; 12] = ["⊢","⊣","≻","≺","⋈","⊙","∈","∋","⊤","⊥","⊞","◻"];
20	/// Every knob, on the command line. Hardcoding them meant a sweep was a rebuild,
21	/// so no sweep was ever run and the numbers that mattered — ring size, learning
22	/// rate, mask fraction, gate weight — were never varied at all.
23	struct Args {
24	    steps: usize, out: String, words: String,
25	    n: usize, batch: usize, mask_frac: f32, gate_lambda: f64,
26	    lr: f64, seed: u64, log_every: usize, val_frac: f64,
27	    d_model: usize, layers: usize, heads: usize, ff_mult: usize,
28	    sigma0: f32, causal: bool,
29	}
30	
31	impl Default for Args {
32	    fn default() -> Self {
33	        Args { steps: 2000, out: "torus_trunk.safetensors".into(), words: "imasm_words.txt".into(),
34	               n: 12, batch: 64, mask_frac: 0.4, gate_lambda: 0.01,
35	               lr: 3e-4, seed: 0x9E3779B97F4A7C15, log_every: 100, val_frac: 0.1,
36	               d_model: 144, layers: 6, heads: 12, ff_mult: 4, sigma0: 1.0, causal: false }
37	    }
38	}
39	
40	const USAGE: &str = "\
41	m2-train [steps] [out.safetensors] [words.txt] [flags]
42	
43	  --ring n          glyphs per window            (default 12)
44	  --batch n         rings per step               (64)
45	  --lr F            AdamW learning rate          (3e-4)
46	  --mask-frac F     fraction of positions masked (0.4)
47	  --gate-lambda F   weight on the gate penalty   (0.01)
48	  --seed n          RNG seed                     (0x9E3779B97F4A7C15)
49	  --log-every n     steps between log lines      (100)
50	  --val-frac F      held-out share of the corpus (0.1)
51	  --d-model n       model width                  (144)
52	  --layers n        depth                        (6)
53	  --heads n         attention heads              (12)
54	  --ff-mult n       feed-forward multiplier      (4)
55	  --alpha F         ring power-law exponent      (1.0)
56	  --causal          mask attention causally      (off)
57	  -h, --help        this
58	";
59	
