//! m2-train — the toroidal trunk as a masked-ring IMASM denoiser, native and
//! Grammar-architected. Learns from structured rings (grammar-biased words over
//! the twelve marks); masks positions and predicts them from the ring's
//! neighbourhood through the circulant attention. Held-out denoising accuracy is
//! reported against the twelve-glyph alphabet, and a sample is scored by the
//! kernel's own verdict (`word_verdict`).
//!
//! Usage: m2-train [steps] [out.safetensors] [words.txt]

use candle_core::{DType, Device, Result, Tensor};
use candle_nn::{AdamW, Optimizer, ParamsAdamW, VarBuilder, VarMap};

use imasm_core::check::{word_verdict, ClosureState};
use imasm_core::classic::Token;
use m2_torus::config::Config;
use m2_torus::model::TorusTrunk;
use vita_native::alphabet;

const GLYPHS: [&str; 12] = ["⊢","⊣","≻","≺","⋈","⊙","∈","∋","⊤","⊥","⊞","◻"];
/// Every knob, on the command line. Hardcoding them meant a sweep was a rebuild,
/// so no sweep was ever run and the numbers that mattered — ring size, learning
/// rate, mask fraction, gate weight — were never varied at all.
struct Args {
    steps: usize, out: String, words: String,
    n: usize, batch: usize, mask_frac: f32, gate_lambda: f64,
    lr: f64, seed: u64, log_every: usize, val_frac: f64,
    d_model: usize, layers: usize, heads: usize, ff_mult: usize,
    sigma0: f32, causal: bool,
}

impl Default for Args {
    fn default() -> Self {
        Args { steps: 2000, out: "torus_trunk.safetensors".into(), words: "imasm_words.txt".into(),
               n: 12, batch: 64, mask_frac: 0.4, gate_lambda: 0.01,
               lr: 3e-4, seed: 0x9E3779B97F4A7C15, log_every: 100, val_frac: 0.1,
               d_model: 144, layers: 6, heads: 12, ff_mult: 4, sigma0: 1.0, causal: false }
    }
}

const USAGE: &str = "\
m2-train [steps] [out.safetensors] [words.txt] [flags]

  --ring n          glyphs per window            (default 12)
