        .lines()
        .map(|l| encode(l.trim()))
        .filter(|w| w.len() >= 2)
        .collect();
    if words.is_empty() {
        anyhow::bail!("no usable rings in {} (need lines of the 12 glyphs, len>=2)", a.corpus);
    }
    println!("[corpus] {} rings from {}", words.len(), a.corpus);

    let cfg = Config {
        d_model: a.d_model,
        n_head: a.n_head,
        d_ff: a.d_ff,
        n_layer: a.n_layer,
        max_len: a.max_len,
    };
    let dev = device()?;
    let varmap = VarMap::new();
    let vb = VarBuilder::from_varmap(&varmap, p4radice::dtype(), &dev);
    let model = DialetheicLlm::new(cfg, vb)?;

    let params = ParamsAdamW { lr: a.lr, ..Default::default() };
    let mut opt = AdamW::new(varmap.all_vars(), params)?;

    let mut rng = rand::rngs::StdRng::seed_from_u64(a.seed);
    use rand::SeedableRng;

    let mut prev_norm: Option<f64> = None;
    for step in 0..a.steps {
        let mut step_loss = 0f32;
        let mut n_seen = 0usize;
        for _ in 0..a.batch {
            let w = &words[rng.gen_range(0..words.len())];
            let n = w.len().min(cfg.max_len);
            if n < 2 {
                continue;
            }
            let ids: Vec<u32> = w[..n].iter().map(|&x| x as u32).collect();
            let input = Tensor::from_vec(ids[..n - 1].to_vec(), (1, n - 1), &dev)?;
            let target = Tensor::from_vec(ids[1..n].to_vec(), (1, n - 1), &dev)?;

            let logits = model.forward(&input)?; // (1, n-1, V)
            let logits = logits.reshape(((n - 1), VOCAB_SIZE))?;
            let target = target.reshape((n - 1,))?;
            let loss = candle_nn::loss::cross_entropy(&logits, &target)?;

            opt.backward_step(&loss)?;
            step_loss += loss.to_scalar::<f32>()?;
            n_seen += 1;
        }
        if n_seen == 0 {
            continue;
        }
        let avg_loss = step_loss / n_seen as f32;

        if step % a.log_every == 0 || step + 1 == a.steps {
            // ⊙ self-modeling: the update the model just made, read back off
            // its own weights, not asserted.
            let mut sq = 0f64;
            for v in varmap.all_vars() {
                let t = v.as_tensor().to_dtype(p4radice::dtype())?;
                let s: f64 = t.sqr()?.sum_all()?.to_scalar::<f32>()? as f64;
                sq += s;
            }
            let norm = sq.sqrt();
            let delta = prev_norm.map(|p| norm - p).unwrap_or(0.0);
            prev_norm = Some(norm);
            println!("step {step:6} loss {avg_loss:.4}  |W|={norm:.4} d|W|={delta:+.4}");
        }
    }

    varmap.save(&a.out)?;
    println!("[anchor] saved {}", a.out);
    Ok(())
}

