        self.log_sigma.exp()?.to_vec1::<f32>()
    }

    /// Debug: is this layer's fork projection moving at all?
    pub fn fork_weight_sumsq(&self) -> Result<f32> {
        self.fork.weight().sqr()?.sum_all()?.to_scalar::<f32>()
    }
    pub fn armt_weight_sumsq(&self) -> Result<f32> {
        self.arm_t.weight().sqr()?.sum_all()?.to_scalar::<f32>()
    }
    pub fn fffuse_weight_sumsq(&self) -> Result<f32> {
        self.ff_fuse.weight().sqr()?.sum_all()?.to_scalar::<f32>()
    }

    /// μ∘δ = id pressure: ‖WᵀW − I‖² on fork and fuse (mean).
    pub fn gate_penalty(&self) -> Result<Tensor> {
        let mut total: Option<Tensor> = None;
        for w in [self.fork.weight(), self.fuse.weight()] {
            let (o, i) = w.dims2()?;
            let g = if o >= i { w.t()?.matmul(w)? } else { w.matmul(&w.t()?)? };
            let n = g.dim(0)?;
            let eye = Tensor::eye(n, DType::F32, w.device())?;
            let pen = (g - eye)?.sqr()?.mean_all()?;
            total = Some(match total { Some(s) => (s + pen)?, None => pen });
        }
        total.unwrap().affine(0.5, 0.0)
    }
}


/// RMS norm written out, because the fused one does not carry a gradient back
/// to what feeds it.
///
/// Measured: with `candle_nn::rms_norm` in place, every parameter behind a norm
/// — fork and fuse behind norm_attn, the two ENGAGR arms and ff_fuse behind
/// norm_ff — held its initial value for the whole run, to eight decimals, while
/// the embedding moved. The residual `x + f(norm(x))` still carried gradient to
/// the embedding through its `x` term, so the loss fell and the trunk looked
/// like it was training when nothing inside a layer ever moved. Six layers of
/// random projection, and the numbers came from the embedding and the tied head
/// alone.
#[derive(Debug)]
pub struct Rms {
    weight: Tensor,
    eps: f64,
}

impl Rms {
    pub fn new(d: usize, eps: f64, vb: VarBuilder) -> Result<Self> {
        let weight = vb.get_with_hints(d, "weight", candle_nn::Init::Const(1.0))?;
        Ok(Rms { weight, eps })
    }
}

impl Module for Rms {
    fn forward(&self, x: &Tensor) -> Result<Tensor> {
        let ms = x.sqr()?.mean_keepdim(candle_core::D::Minus1)?;
        let inv = (ms + self.eps)?.sqrt()?.recip()?;
        x.broadcast_mul(&inv)?.broadcast_mul(&self.weight)
    }
}

/// The trunk: toroidal embed → L layers → norm → tied head.
pub struct TorusTrunk {
    embed: TorusEmbed,
    pub layers: Vec<Layer>,
    norm: Rms,
    cfg: Config,
}

impl TorusTrunk {
    pub fn new(cfg: Config, vb: VarBuilder, dev: &Device) -> Result<Self> {
        let embed = TorusEmbed::new(&cfg, vb.pp("embed"), dev)?;
        let mut layers = Vec::with_capacity(cfg.layers);
        for i in 0..cfg.layers {
            layers.push(Layer::new(&cfg, vb.pp(format!("layer{i}")))?);
        }
        let norm = Rms::new(cfg.d_model, 1e-6, vb.pp("norm"))?;
        Ok(TorusTrunk { embed, layers, norm, cfg })
    }

    /// Debug: is the embedding moving?
    pub fn embed_sumsq(&self) -> Result<f32> {
        self.embed.table()?.sqr()?.sum_all()?.to_scalar::<f32>()
    }

    /// ids: (b,t) → logits (b,t,vocab). Head tied to the residual embedding.
    pub fn forward(&self, ids: &Tensor) -> Result<Tensor> {
        let mut x = self.embed.forward(ids)?;
        for l in &self.layers {
            x = l.forward(&x)?;
        }
        x = self.norm.forward(&x)?;
        // tied head onto the FULL embedding table (seed + residual)
        let w = self.embed.table()?; // (vocab, d)
        let (b, t, d) = x.dims3()?;
        let logits = x.reshape((b * t, d))?.matmul(&w.t()?)?;
        logits.reshape((b, t, self.cfg.vocab))
    }

    /// Debug probe: sum of every layer's log_sigma.
    pub fn log_sigma_sum(&self) -> Result<Tensor> {
        let mut total: Option<Tensor> = None;
        for l in &self.layers {
            let p = l.log_sigma_sum()?;
            total = Some(match total { Some(s) => (s + p)?, None => p });
        }
        total.unwrap().affine(1.0, 0.0)
    }

    pub fn gate_penalty(&self) -> Result<Tensor> {
        let mut total: Option<Tensor> = None;
        for l in &self.layers {
            let p = l.gate_penalty()?;
            total = Some(match total { Some(s) => (s + p)?, None => p });
        }
        total.unwrap().affine(1.0 / self.layers.len() as f64, 0.0)
    }

    pub fn config(&self) -> &Config { &self.cfg }
}

