use candle_core::{DType, Device, Result, Tensor, D};

/// μ∘δ = id pressure: ‖WᵀW − I‖² (or WWᵀ, whichever side is smaller), same
/// penalty m2_torus applies to its fork/fuse pair. Nothing in this model
/// coupled the comultiplicative arm (∈: q/k/v splitting the stream,
/// affirm_in/reject_in splitting into expert space) to the multiplicative
/// arm (∋: o fusing heads back to the stream, affirm_out/reject_out fusing
/// experts back) until this existed -- a SIC-POVM's analysis/synthesis maps
/// have to compose to identity for the frame to be information-complete,
/// and with no pressure toward that, gradient descent found the cheapest
/// way to satisfy next-glyph loss without ever using the split/fuse
/// structure at all (bare ⊢⊣, verdict N on 83% of generated samples).
fn frobenius_penalty(w: &Tensor) -> Result<Tensor> {
    let (o, i) = w.dims2()?;
    let g = if o >= i { w.t()?.matmul(w)? } else { w.matmul(&w.t()?)? };
    let n = g.dim(0)?;
    let eye = Tensor::eye(n, DType::F32, w.device())?;
    (g - eye)?.sqr()?.mean_all()
}

