p4-gen [flags]

  --ckpt F          checkpoint path                  (p4radice.safetensors)
  --seed W          seed word, built from the twelve glyphs   (⊢)
  --n-gen n         glyphs to sample                 (40)
  --d-model n       must match the checkpoint         (64)
  --n-head n        must match the checkpoint         (4)
  --d-ff n          must match the checkpoint         (256)
  --n-layer n       must match the checkpoint         (4)
  --max-len n       must match the checkpoint         (128)
  -h, --help        this
";

fn parse_args() -> Args {
    let mut a = Args::default();
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0usize;
    let val = |i: &mut usize, argv: &[String], name: &str| -> String {
        *i += 1;
        argv.get(*i).cloned().unwrap_or_else(|| {
            eprintln!("{name} wants a value");
            std::process::exit(2)
        })
    };
    while i < argv.len() {
        let t = argv[i].clone();
        match t.as_str() {
            "-h" | "--help" => {
                print!("{USAGE}");
                std::process::exit(0)
            }
            "--ckpt" => a.ckpt = val(&mut i, &argv, "--ckpt"),
            "--seed" => a.seed_word = val(&mut i, &argv, "--seed"),
            "--n-gen" => a.n_gen = val(&mut i, &argv, "--n-gen").parse().expect("--n-gen"),
            "--d-model" => a.d_model = val(&mut i, &argv, "--d-model").parse().expect("--d-model"),
            "--n-head" => a.n_head = val(&mut i, &argv, "--n-head").parse().expect("--n-head"),
            "--d-ff" => a.d_ff = val(&mut i, &argv, "--d-ff").parse().expect("--d-ff"),
            "--n-layer" => a.n_layer = val(&mut i, &argv, "--n-layer").parse().expect("--n-layer"),
            "--max-len" => a.max_len = val(&mut i, &argv, "--max-len").parse().expect("--max-len"),
            other => {
                eprintln!("unknown flag {other}\n{USAGE}");
                std::process::exit(2)
            }
        }
        i += 1;
    }
    a
}

fn main() -> anyhow::Result<()> {
    let a = parse_args();

    let cfg = Config {
        d_model: a.d_model,
        n_head: a.n_head,
        d_ff: a.d_ff,
        n_layer: a.n_layer,
        max_len: a.max_len,
    };
    let dev = device()?;
    let mut varmap = VarMap::new();
    let vb = VarBuilder::from_varmap(&varmap, DType::F32, &dev);
    let model = DialetheicLlm::new(cfg, vb)?;
    varmap.load(&a.ckpt)?;

    let mut ids = encode(&a.seed_word);
    if ids.is_empty() {
        anyhow::bail!("seed word must be built from the twelve glyphs");
    }
    let mut rng = rand::thread_rng();

    for _ in 0..a.n_gen {
        let n = ids.len().min(cfg.max_len);
        let window: Vec<u32> = ids[ids.len() - n..].iter().map(|&x| x as u32).collect();
        let input = Tensor::from_vec(window, (1, n), &dev)?;
        let logits = model.forward(&input)?; // (1, n, V)
        let last = logits.i((0, n - 1))?.to_dtype(DType::F32)?;
        let probs = candle_nn::ops::softmax(&last, 0)?;
        let probs: Vec<f32> = probs.to_vec1()?;

        let r: f32 = rng.gen();
        let mut acc = 0f32;
        let mut next = VOCAB_SIZE - 1;
        for (i, &p) in probs.iter().enumerate() {
            acc += p;
            if r <= acc {
                next = i;
                break;
            }
        }
        ids.push(next);
        if glyph_of(next) == '⊣' {
            break;
        }
    }

    println!("{}", decode(&ids));
    Ok(())
