/// A word is a ring and ROTAT is the cyclic shift: every rotation is the
/// same object, so training a fixed cut of each ring forever teaches only
/// one linearization of it, never the ring itself. `r` in `0..ids.len()`.
pub fn rotate(ids: &[usize], r: usize) -> Vec<usize> {
    if ids.is_empty() {
        return Vec::new();
    }
    let r = r % ids.len();
    ids[r..].iter().chain(ids[..r].iter()).copied().collect()
}

