1	//! p4radice — a transformer whose attention and feed-forward blocks
2	//! never collapse T and F into one number before they've been held.
3	//!
4	//! Source: `ob3ect/digital/dialetheic_paraconsistent_native_llm
5	//! /dialetheic_paraconsistent_native_llm_ob3ect.json`, `phases.phase_4.steps`.
6	//! That sequence is not a description of a transformer, it is a build order:
7	//! `∈` split heads, `⊤` affirm arm, `⊥` reject arm, `⊞` HOLD both, `∋` fuse.
8	//! A standard transformer computes `⊤` and `⊥` as one step — masked softmax
9	//! sends the disallowed (future) logits to -inf before the softmax even
10	//! runs, so the "reject" information never exists as a value anywhere. This
11	//! model computes both arms as real tensors, concatenates them (the `⊞`
12	//! hold), and only reduces dimension afterward through a learned projection
13	//! (the `∋` fuse) — so what to do with the contradiction is learned, not
14	//! erased by the architecture in advance.
15	//!
16	//! The feed-forward block repeats the same shape as a two-expert version:
17	//! an affirm expert and a reject expert are BOTH always evaluated (no
18	//! top-1 routing, which would discard one arm the way masked softmax
19	//! discards the future), and a learned gate blends them per token.
20	
21	use candle_core::{DType, Device, Result, Tensor, D};
22	
23	/// μ∘δ = id pressure: ‖WᵀW − I‖² (or WWᵀ, whichever side is smaller), same
24	/// penalty m2_torus applies to its fork/fuse pair. Nothing in this model
25	/// coupled the comultiplicative arm (∈: q/k/v splitting the stream,
26	/// affirm_in/reject_in splitting into expert space) to the multiplicative
27	/// arm (∋: o fusing heads back to the stream, affirm_out/reject_out fusing
28	/// experts back) until this existed -- a SIC-POVM's analysis/synthesis maps
29	/// have to compose to identity for the frame to be information-complete,
30	/// and with no pressure toward that, gradient descent found the cheapest
31	/// way to satisfy next-glyph loss without ever using the split/fuse
32	/// structure at all (bare ⊢⊣, verdict N on 83% of generated samples).
33	fn frobenius_penalty(w: &Tensor) -> Result<Tensor> {
34	    let (o, i) = w.dims2()?;
35	    let g = if o >= i { w.t()?.matmul(w)? } else { w.matmul(&w.t()?)? };
36	    let n = g.dim(0)?;
37	    let eye = Tensor::eye(n, DType::F32, w.device())?;
38	    (g - eye)?.sqr()?.mean_all()
39	}
40	use candle_nn::{
41	    embedding, layer_norm, linear, Embedding, LayerNorm, LayerNormConfig, Linear, Module,
42	    VarBuilder,
43	};
44	
45	/// The twelve marks, in kernel slot order. `id_of`/`glyph_of` are the whole
46	/// vocabulary — this is a from-scratch build, so it does not reach into
47	/// imasm_core or vita_native for the alphabet. AFWD/AREV are ≻/≺: the
48	/// canonical marks, matching imasm_core::classic::Token::parse. The on-disk
49	/// corpus (daydr33m/m2_torus/ob3ect_words.txt) spells them as ASCII '>'/'<'
50	/// instead — a retired spelling, not a second alphabet — so `encode`
51	/// normalizes those two characters to the canonical marks before lookup,
52	/// the same way imasm_core's own `normalize` does for the kernel.
53	pub const GLYPHS: [char; 12] = [
54	    '⊢', '⊣', '≻', '≺', '⋈', '⊤', '∈', '∋', '⊙', '⊥', '⊞', '◻',
55	];
56	pub const VOCAB_SIZE: usize = GLYPHS.len();
57	
58	pub fn id_of(c: char) -> Option<usize> {
59	    GLYPHS.iter().position(|&g| g == c)
60	}
61	
62	pub fn glyph_of(id: usize) -> char {
63	    GLYPHS[id]
64	}
65	
66	/// Retired ASCII spellings still found in stored corpora, mapped onto the
67	/// canonical marks before `id_of` ever sees them.
68	fn normalize_char(c: char) -> char {
69	    match c {
70	        '>' => '≻',
71	        '<' => '≺',
72	        other => other,
73	    }
74	}
75	
76	pub fn encode(word: &str) -> Vec<usize> {
77	    word.chars().map(normalize_char).filter_map(id_of).collect()
78	}
79	
80	pub fn decode(ids: &[usize]) -> String {
81	    ids.iter().map(|&i| glyph_of(i)).collect()
82	}
