84	/// A word is a ring and ROTAT is the cyclic shift: every rotation is the
85	/// same object, so training a fixed cut of each ring forever teaches only
86	/// one linearization of it, never the ring itself. `r` in `0..ids.len()`.
87	pub fn rotate(ids: &[usize], r: usize) -> Vec<usize> {
88	    if ids.is_empty() {
89	        return Vec::new();
90	    }
91	    let r = r % ids.len();
92	    ids[r..].iter().chain(ids[..r].iter()).copied().collect()
93	}
