95	#[derive(Clone, Copy, Debug)]
96	pub struct Config {
97	    pub d_model: usize,
98	    pub n_head: usize,
99	    pub d_ff: usize,
100	    pub n_layer: usize,
101	    pub max_len: usize,
102	}
103	
104	impl Default for Config {
105	    fn default() -> Self {
106	        Self {
107	            d_model: 64,
108	            n_head: 4,
109	            d_ff: 256,
110	            n_layer: 4,
111	            max_len: 128,
112	        }
113	    }
114	}
115	
116	/// The `∈ ⊤ ⊥ ⊞ ∋` shape applied to attention. Affirm is ordinary causal
117	/// softmax attention. Reject is softmax attention over exactly the positions
118	/// affirm was forbidden from seeing — the future — so it is a real signal,
119	/// not affirm's mirror image. Both are concatenated (held) per head before
120	/// the output projection fuses them down to d_model.
121	pub struct DialetheicAttention {
122	    q: Linear,
123	    k: Linear,
124	    v: Linear,
125	    o: Linear,
126	    n_head: usize,
127	    d_head: usize,
128	}
129	
130	impl DialetheicAttention {
131	    pub fn new(d_model: usize, n_head: usize, vb: VarBuilder) -> Result<Self> {
132	        assert_eq!(d_model % n_head, 0, "d_model must divide evenly into n_head");
133	        let d_head = d_model / n_head;
134	        Ok(Self {
135	            q: linear(d_model, d_model, vb.pp("q"))?,
136	            k: linear(d_model, d_model, vb.pp("k"))?,
137	            v: linear(d_model, d_model, vb.pp("v"))?,
138	            // held width is 2*d_model (affirm ++ reject, per head, concatenated
139	            // back together across heads), fused down to d_model here.
140	            o: linear(2 * d_model, d_model, vb.pp("o"))?,
141	            n_head,
142	            d_head,
143	        })
144	    }
145	
146	    /// x: (batch, seq, d_model). Returns (batch, seq, d_model).
147	    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
148	        let (b, n, _) = x.dims3()?;
149	        let h = self.n_head;
150	        let dh = self.d_head;
151	        let dev = x.device();
152	
153	        let split_heads = |t: &Tensor| -> Result<Tensor> {
154	            t.reshape((b, n, h, dh))?.transpose(1, 2)?.contiguous() // (b,h,n,dh)
155	        };
156	        let q = split_heads(&self.q.forward(x)?)?;
157	        let k = split_heads(&self.k.forward(x)?)?;
158	        let v = split_heads(&self.v.forward(x)?)?;
159	
160	        let scale = 1f64 / (dh as f64).sqrt();
161	        let scores = (q.matmul(&k.transpose(D::Minus2, D::Minus1)?)? * scale)?; // (b,h,n,n)
162	
163	        // allowed[i][j] = 1 if j<=i (causal), 0 otherwise. neg_inf on the
164	        // opposite side gives affirm (causal) and reject (anti-causal, i.e.
165	        // the future) as two genuinely different softmax distributions.
166	        let mut allow = vec![0f32; n * n];
167	        let mut deny = vec![0f32; n * n];
168	        for i in 0..n {
169	            for j in 0..n {
170	                if j <= i {
171	                    allow[i * n + j] = 0.0;
172	                    deny[i * n + j] = f32::NEG_INFINITY;
173	                } else {
174	                    allow[i * n + j] = f32::NEG_INFINITY;
175	                    deny[i * n + j] = 0.0;
176	                }
177	            }
178	        }
179	        // Row i=n-1 has no future at all, so every entry of that row in
180	        // `deny` is -inf and its softmax is 0/0 = NaN before row_mask ever
181	        // gets a chance to zero it -- NaN * 0 is still NaN. Give that row a
182	        // finite (uniform) softmax instead; row_mask below zeroes its
183	        // contribution afterward on a real number, not an already-NaN one.
184	        for j in 0..n {
185	            deny[(n - 1) * n + j] = 0.0;
186	        }
187	        let allow_mask = Tensor::from_vec(allow, (1, 1, n, n), dev)?.to_dtype(scores.dtype())?;
188	        let deny_mask = Tensor::from_vec(deny, (1, 1, n, n), dev)?.to_dtype(scores.dtype())?;
189	
190	        let affirm_logits = scores.broadcast_add(&allow_mask)?;
191	        let reject_logits = scores.broadcast_add(&deny_mask)?;
192	
193	        let affirm = candle_nn::ops::softmax(&affirm_logits, D::Minus1)?;
194	        // row i=n-1 has no future: every entry of reject_logits[n-1] is
195	        // -inf, softmax would be NaN. Zero that row's weights explicitly --
196	        // an empty reject arm is a real value (nothing to hold), not a
197	        // numerical accident.
198	        let reject_raw = candle_nn::ops::softmax(&reject_logits, D::Minus1)?;
199	        let mut row_has_future = vec![1f32; n];
200	        row_has_future[n - 1] = 0.0;
201	        let row_mask = Tensor::from_vec(row_has_future, (1, 1, n, 1), dev)?
202	            .to_dtype(reject_raw.dtype())?;
203	        let reject = reject_raw.broadcast_mul(&row_mask)?;
204	
205	        let affirm_out = affirm.matmul(&v)?; // (b,h,n,dh)
206	        let reject_out = reject.matmul(&v)?; // (b,h,n,dh)
207	
208	        // HOLD: concat affirm and reject per head, then concat heads.
209	        let held = Tensor::cat(&[&affirm_out, &reject_out], D::Minus1)?; // (b,h,n,2dh)
210	        let held = held.transpose(1, 2)?.contiguous()?.reshape((b, n, h * 2 * dh))?;
211	
212	        // FUSE: one learned projection back to d_model.
213	        self.o.forward(&held)
214	    }
215	
216	    /// δ = q,k,v (the stream splitting into evaluation arms); μ = o (the
217	    /// held arms fusing back into the stream).
218	    pub fn gate_penalty(&self) -> Result<Tensor> {
219	        let mut total = frobenius_penalty(self.q.weight())?;
220	        total = (total + frobenius_penalty(self.k.weight())?)?;
221	        total = (total + frobenius_penalty(self.v.weight())?)?;
222	        total = (total + frobenius_penalty(self.o.weight())?)?;
223	        total.affine(0.25, 0.0)
224	    }
225	}
226	
227	/// The `∈ ⊤ ⊥ ⊞ ∋` shape applied to the feed-forward block: an affirm
228	/// expert and a reject expert are both always evaluated (never top-1
229	/// routed — routing would re-introduce the same collapse this whole model
230	/// is built to avoid), and a learned per-token gate blends the two without
231	/// ever letting either weight reach exactly zero.
232	pub struct DialetheicFfn {
233	    affirm_in: Linear,
234	    affirm_out: Linear,
235	    reject_in: Linear,
236	    reject_out: Linear,
237	    gate: Linear,
238	}
239	
240	impl DialetheicFfn {
241	    pub fn new(d_model: usize, d_ff: usize, vb: VarBuilder) -> Result<Self> {
242	        Ok(Self {
243	            affirm_in: linear(d_model, d_ff, vb.pp("affirm_in"))?,
244	            affirm_out: linear(d_ff, d_model, vb.pp("affirm_out"))?,
245	            reject_in: linear(d_model, d_ff, vb.pp("reject_in"))?,
246	            reject_out: linear(d_ff, d_model, vb.pp("reject_out"))?,
247	            gate: linear(d_model, 1, vb.pp("gate"))?,
248	        })
249	    }
250	
251	    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
252	        let affirm = self.affirm_out.forward(&self.affirm_in.forward(x)?.gelu()?)?;
253	        let reject = self.reject_out.forward(&self.reject_in.forward(x)?.gelu()?)?;
254	        // sigmoid gate in (0,1): both arms always contribute something,
255	        // matching "coexist without collapse" rather than a hard switch.
256	        let g = candle_nn::ops::sigmoid(&self.gate.forward(x)?)?; // (b,n,1)
257	        let one_minus_g = (1.0 - &g)?;
258	        affirm.broadcast_mul(&g)? + reject.broadcast_mul(&one_minus_g)?
259	    }
260	
261	    /// δ = affirm_in/reject_in (splitting the stream into expert space);
262	    /// μ = affirm_out/reject_out (fusing each expert's space back).
263	    pub fn gate_penalty(&self) -> Result<Tensor> {
264	        let mut total = frobenius_penalty(self.affirm_in.weight())?;
265	        total = (total + frobenius_penalty(self.reject_in.weight())?)?;
266	        total = (total + frobenius_penalty(self.affirm_out.weight())?)?;
267	        total = (total + frobenius_penalty(self.reject_out.weight())?)?;
268	        total.affine(0.25, 0.0)
269	    }
270	}
271	
272	pub struct Block {
273	    ln1: LayerNorm,
274	    attn: DialetheicAttention,
275	    ln2: LayerNorm,
276	    ffn: DialetheicFfn,
277	}
278	
279	impl Block {
280	    pub fn new(cfg: &Config, vb: VarBuilder) -> Result<Self> {
281	        let lncfg = LayerNormConfig::default();
282	        Ok(Self {
283	            ln1: layer_norm(cfg.d_model, lncfg, vb.pp("ln1"))?,
284	            attn: DialetheicAttention::new(cfg.d_model, cfg.n_head, vb.pp("attn"))?,
285	            ln2: layer_norm(cfg.d_model, lncfg, vb.pp("ln2"))?,
286	            ffn: DialetheicFfn::new(cfg.d_model, cfg.d_ff, vb.pp("ffn"))?,
287	        })
288	    }
289	
290	    /// `⋈` residual composition around both sub-blocks.
291	    pub fn forward(&self, x: &Tensor) -> Result<Tensor> {
292	        let x = (x + self.attn.forward(&self.ln1.forward(x)?)?)?;
293	        let x = (&x + self.ffn.forward(&self.ln2.forward(&x)?)?)?;
294	        Ok(x)
295	    }
296	
297	    pub fn gate_penalty(&self) -> Result<Tensor> {
298	        (self.attn.gate_penalty()? + self.ffn.gate_penalty()?)?.affine(0.5, 0.0)
299	    }
300	}
301	
302	pub struct DialetheicLlm {
303	    tok_emb: Embedding,
304	    pos_emb: Embedding,
305	    blocks: Vec<Block>,
306	    ln_f: LayerNorm,
307	    head: Linear,
308	    pub cfg: Config,
309	}
310	
311	impl DialetheicLlm {
312	    pub fn new(cfg: Config, vb: VarBuilder) -> Result<Self> {
313	        let tok_emb = embedding(VOCAB_SIZE, cfg.d_model, vb.pp("tok_emb"))?;
314	        let pos_emb = embedding(cfg.max_len, cfg.d_model, vb.pp("pos_emb"))?;
315	        let mut blocks = Vec::with_capacity(cfg.n_layer);
316	        for i in 0..cfg.n_layer {
317	            blocks.push(Block::new(&cfg, vb.pp(format!("block{i}")))?);
318	        }
319	        let ln_f = layer_norm(cfg.d_model, LayerNormConfig::default(), vb.pp("ln_f"))?;
320	        let head = linear(cfg.d_model, VOCAB_SIZE, vb.pp("head"))?;
321	        Ok(Self {
322	            tok_emb,
323	            pos_emb,
324	            blocks,
325	            ln_f,
326	            head,
327	            cfg,
328	        })
329	    }
330	
331	    /// ids: (batch, seq) of glyph ids. Returns logits (batch, seq, VOCAB_SIZE).
332	    pub fn forward(&self, ids: &Tensor) -> Result<Tensor> {
333	        let (b, n) = ids.dims2()?;
334	        let dev = ids.device();
335	        let pos = Tensor::arange(0u32, n as u32, dev)?
336	            .reshape((1, n))?
337	            .broadcast_as((b, n))?;
338	        let mut x = (self.tok_emb.forward(ids)? + self.pos_emb.forward(&pos)?)?;
339	        for blk in &self.blocks {
340	            x = blk.forward(&x)?;
341	        }
342	        let x = self.ln_f.forward(&x)?;
343	        self.head.forward(&x)
344	    }
345	
346	    /// μ∘δ = id pressure, averaged over every block. Add to the training
347	    /// loss (weighted) so the split/fuse structure is not free to collapse.
348	    pub fn gate_penalty(&self) -> Result<Tensor> {
349	        let mut total: Option<Tensor> = None;
350	        for b in &self.blocks {
351	            let p = b.gate_penalty()?;
352	            total = Some(match total {
353	                Some(s) => (s + p)?,
354	                None => p,
355	            });
356	        }
357	        total.unwrap().affine(1.0 / self.blocks.len() as f64, 0.0)
358	    }
359	}
