361	pub fn device() -> Result<Device> {
362	    if candle_core::utils::cuda_is_available() {
363	        Device::new_cuda(0)
364	    } else {
365	        Ok(Device::Cpu)
366	    }
367	}
368	
369	pub fn dtype() -> DType {
370	    DType::F32
371	}
