/// The real vocabulary: one BPE tokenizer trained over ig-docs prose, the
/// ob3ect opcode rings, and their Shavian tuples together (`p4-train-tokenizer`),
/// not the twelve-glyph GLYPHS table above. GLYPHS/encode/decode/rotate stay
/// for pure-IMASM utilities (the closure check in gen.rs reasons about raw
/// marks, not subword token ids) but no longer back the model itself.
pub mod tok {
    use tokenizers::Tokenizer;

    pub fn load(path: &str) -> Result<Tokenizer, Box<dyn std::error::Error + Send + Sync>> {
        Tokenizer::from_file(path)
    }

    pub fn encode(
        t: &Tokenizer,
        text: &str,
    ) -> Result<Vec<u32>, Box<dyn std::error::Error + Send + Sync>> {
        Ok(t.encode(text, false)?.get_ids().to_vec())
    }

    pub fn decode(
        t: &Tokenizer,
        ids: &[u32],
    ) -> Result<String, Box<dyn std::error::Error + Send + Sync>> {
        Ok(t.decode(ids, true)?)
    }
}

