1	//! p4-train — steps 19-23 of the spec: backprop, chain the gradient through
2	//! the network, have the model recognize its own update (⊙ — made concrete
3	//! below as the printed per-step parameter-delta norm, not a metaphor),
4	//! hold the stability/adaptation tension (AdamW's own job), anchor the
5	//! final state (checkpoint save, ⊣).
6	//!
7	//! Usage: p4-train [flags]
8	
9	use candle_core::Tensor;
10	use candle_nn::{AdamW, Optimizer, ParamsAdamW, VarBuilder, VarMap};
11	use p4radice::{device, encode, rotate, Config, DialetheicLlm, VOCAB_SIZE};
12	use rand::Rng;
13	use std::io::Read;
14	
15	/// Every knob, on the command line. Hardcoding them means a sweep is a
16	/// rebuild, so no sweep ever gets run and the numbers that matter -- width,
17	/// depth, learning rate -- never get varied at all.
18	struct Args {
19	    corpus: String,
20	    out: String,
21	    steps: usize,
22	    lr: f64,
23	    gate_lambda: f64,
24	    batch: usize,
25	    seed: u64,
26	    log_every: usize,
27	    d_model: usize,
28	    n_head: usize,
29	    d_ff: usize,
30	    n_layer: usize,
31	    max_len: usize,
32	}
33	
34	impl Default for Args {
35	    fn default() -> Self {
36	        Args {
37	            corpus: "/home/mrnob0dy666/imsgct/daydr33m/m2_torus/ob3ect_words.txt".into(),
38	            out: "/home/mrnob0dy666/imsgct/p4radice/p4radice.safetensors".into(),
39	            steps: 2000,
40	            lr: 3e-4,
41	            gate_lambda: 0.01,
42	            batch: 8,
43	            seed: 0x9E3779B97F4A7C15,
44	            log_every: 100,
45	            d_model: 64,
46	            n_head: 4,
47	            d_ff: 256,
48	            n_layer: 4,
49	            max_len: 128,
50	        }
51	    }
52	}
53	
54	const USAGE: &str = "\
55	p4-train [flags]
56	
57	  --corpus F        newline-separated glyph rings   (ob3ect_words.txt)
58	  --out F           checkpoint path                 (p4radice.safetensors)
59	  --steps n         training steps                  (2000)
60	  --lr F            AdamW learning rate              (3e-4)
61	  --gate-lambda F   weight on the mu∘delta=id penalty (0.01)
62	  --batch n         rings per step                   (8)
63	  --seed n          RNG seed                         (0x9E3779B97F4A7C15)
64	  --log-every n     steps between log lines          (100)
65	  --d-model n       model width                      (64)
66	  --n-head n        attention heads                  (4)
67	  --d-ff n          feed-forward width                (256)
68	  --n-layer n       depth                            (4)
69	  --max-len n       max sequence length               (128)
70	  -h, --help        this
71	";
72	
73	fn parse_args() -> Args {
74	    let mut a = Args::default();
75	    let argv: Vec<String> = std::env::args().skip(1).collect();
76	    let mut i = 0usize;
77	    let val = |i: &mut usize, argv: &[String], name: &str| -> String {
78	        *i += 1;
79	        argv.get(*i).cloned().unwrap_or_else(|| {
80	            eprintln!("{name} wants a value");
81	            std::process::exit(2)
82	        })
83	    };
84	    while i < argv.len() {
85	        let t = argv[i].clone();
86	        match t.as_str() {
87	            "-h" | "--help" => {
88	                print!("{USAGE}");
89	                std::process::exit(0)
90	            }
91	            "--corpus" => a.corpus = val(&mut i, &argv, "--corpus"),
92	            "--out" => a.out = val(&mut i, &argv, "--out"),
93	            "--steps" => a.steps = val(&mut i, &argv, "--steps").parse().expect("--steps"),
94	            "--lr" => a.lr = val(&mut i, &argv, "--lr").parse().expect("--lr"),
95	            "--gate-lambda" => {
96	                a.gate_lambda = val(&mut i, &argv, "--gate-lambda").parse().expect("--gate-lambda")
97	            }
98	            "--batch" => a.batch = val(&mut i, &argv, "--batch").parse().expect("--batch"),
99	            "--seed" => a.seed = val(&mut i, &argv, "--seed").parse().expect("--seed"),
100	            "--log-every" => {
101	                a.log_every = val(&mut i, &argv, "--log-every").parse().expect("--log-every")
102	            }
103	            "--d-model" => a.d_model = val(&mut i, &argv, "--d-model").parse().expect("--d-model"),
104	            "--n-head" => a.n_head = val(&mut i, &argv, "--n-head").parse().expect("--n-head"),
105	            "--d-ff" => a.d_ff = val(&mut i, &argv, "--d-ff").parse().expect("--d-ff"),
106	            "--n-layer" => a.n_layer = val(&mut i, &argv, "--n-layer").parse().expect("--n-layer"),
107	            "--max-len" => a.max_len = val(&mut i, &argv, "--max-len").parse().expect("--max-len"),
108	            other => {
109	                eprintln!("unknown flag {other}\n{USAGE}");
110	                std::process::exit(2)
111	            }
112	        }
113	        i += 1;
114	    }
115	    if a.d_model % a.n_head != 0 {
116	        eprintln!("--d-model ({}) must divide by --n-head ({})", a.d_model, a.n_head);
117	        std::process::exit(2)
118	    }
119	    a
120	}
121	
122	fn main() -> anyhow::Result<()> {
123	    let a = parse_args();
124	
125	    let mut raw = String::new();
126	    std::fs::File::open(&a.corpus)?.read_to_string(&mut raw)?;
127	    let words: Vec<Vec<usize>> = raw
128	        .lines()
129	        .map(|l| encode(l.trim()))
130	        .filter(|w| w.len() >= 2)
131	        .collect();
132	    if words.is_empty() {
133	        anyhow::bail!("no usable rings in {} (need lines of the 12 glyphs, len>=2)", a.corpus);
134	    }
135	    println!("[corpus] {} rings from {}", words.len(), a.corpus);
136	
137	    let cfg = Config {
138	        d_model: a.d_model,
139	        n_head: a.n_head,
140	        d_ff: a.d_ff,
141	        n_layer: a.n_layer,
142	        max_len: a.max_len,
143	    };
144	    let dev = device()?;
145	    let varmap = VarMap::new();
146	    let vb = VarBuilder::from_varmap(&varmap, p4radice::dtype(), &dev);
147	    let model = DialetheicLlm::new(cfg, vb)?;
148	
149	    let params = ParamsAdamW { lr: a.lr, ..Default::default() };
150	    let mut opt = AdamW::new(varmap.all_vars(), params)?;
151	
152	    let mut rng = rand::rngs::StdRng::seed_from_u64(a.seed);
153	    use rand::SeedableRng;
154	
155	    let mut prev_norm: Option<f64> = None;
156	    for step in 0..a.steps {
157	        let mut step_ce = 0f32;
158	        let mut step_gate = 0f32;
159	        let mut n_seen = 0usize;
160	        for _ in 0..a.batch {
161	            let w = &words[rng.gen_range(0..words.len())];
162	            // ROTAT augmentation: a word is a ring, every cut is the same
163	            // object, so a fixed cut per ring forever only ever teaches one
164	            // linearization of it. Rotate the whole ring before windowing,
165	            // not after -- windowing a rotation is still a valid cyclic
166	            // read; rotating a window would not be.
167	            let w = rotate(w, rng.gen_range(0..w.len()));
168	            let n = w.len().min(cfg.max_len);
169	            if n < 2 {
170	                continue;
171	            }
172	            let ids: Vec<u32> = w[..n].iter().map(|&x| x as u32).collect();
173	            let input = Tensor::from_vec(ids[..n - 1].to_vec(), (1, n - 1), &dev)?;
174	            let target = Tensor::from_vec(ids[1..n].to_vec(), (1, n - 1), &dev)?;
175	
176	            let logits = model.forward(&input)?; // (1, n-1, V)
177	            let logits = logits.reshape(((n - 1), VOCAB_SIZE))?;
178	            let target = target.reshape((n - 1,))?;
179	            let ce = candle_nn::loss::cross_entropy(&logits, &target)?;
180	            let gate = model.gate_penalty()?;
181	            let loss = (&ce + (&gate * a.gate_lambda)?)?;
182	
183	            opt.backward_step(&loss)?;
184	            step_ce += ce.to_scalar::<f32>()?;
185	            step_gate += gate.to_scalar::<f32>()?;
186	            n_seen += 1;
187	        }
188	        if n_seen == 0 {
189	            continue;
190	        }
191	        let avg_ce = step_ce / n_seen as f32;
192	        let avg_gate = step_gate / n_seen as f32;
193	
194	        if step % a.log_every == 0 || step + 1 == a.steps {
195	            // ⊙ self-modeling: the update the model just made, read back off
196	            // its own weights, not asserted.
197	            let mut sq = 0f64;
198	            for v in varmap.all_vars() {
199	                let t = v.as_tensor().to_dtype(p4radice::dtype())?;
200	                let s: f64 = t.sqr()?.sum_all()?.to_scalar::<f32>()? as f64;
201	                sq += s;
202	            }
203	            let norm = sq.sqrt();
204	            let delta = prev_norm.map(|p| norm - p).unwrap_or(0.0);
205	            prev_norm = Some(norm);
206	            println!(
207	                "step {step:6} loss {avg_ce:.4} gate {avg_gate:.4}  |W|={norm:.4} d|W|={delta:+.4}"
208	            );
209	        }
210	    }
211	
212	    varmap.save(&a.out)?;
213	    println!("[anchor] saved {}", a.out);
214	    Ok(())
215	}
