//! p4-gen — autoregressive sampling. Recomputes the full forward pass every
//! step rather than an incremental KV cache -- step 18 of the spec ("fix
//! the key-value pairs into the KV cache as a permanent record") is not
//! built here; this stands in for it at the cost of recomputing the whole
//! prefix on every generated glyph.
//!
//! Usage: p4-gen [flags]
//!
//! --d-model/--n-head/--d-ff/--n-layer/--max-len must match whatever the
//! checkpoint was trained with -- they are not stored in the .safetensors
//! file, so a mismatch loads silently wrong weights into the wrong shapes
//! and candle will error on the first tensor whose size does not match.

use candle_core::{DType, IndexOp, Tensor};
use candle_nn::{VarBuilder, VarMap};
use imasm_core::check::word_verdict;
use imasm_core::classic::Token;
use p4radice::{decode, device, encode, glyph_of, Config, DialetheicLlm, VOCAB_SIZE};
use rand::Rng;

