/// Whether the ring is actually closed, per the same kernel check the
/// corpus itself was measured against -- not whether it merely sampled a
/// ⊣. ⊣ is not a hard terminator in the training data: 18% of corpus
/// rings carry it mid-ring, so stopping on the glyph alone manufactures
/// rings (bare ⊢⊣, 0 occurrences in 1703 real rings) the model never
/// actually learned to produce.
fn is_really_closed(ids: &[usize]) -> bool {
    let toks: Vec<Token> = ids
        .iter()
        .filter_map(|&i| Token::parse(&glyph_of(i).to_string()))
        .collect();
    matches!(word_verdict(&toks).0, 'T' | 'B')
}

