//! the network, have the model recognize its own update (⊙ — made concrete
//! below as the printed per-step parameter-delta norm, not a metaphor),
//! hold the stability/adaptation tension (AdamW's own job), anchor the
//! final state (checkpoint save, ⊣).
//!
//! Trains over the REAL combined corpus now — ig-docs prose, the ob3ect
//! opcode rings, and their Shavian tuples, tokenized as one vocabulary by
//! `p4-train-tokenizer`'s tokenizer.json, not the old fixed 12-glyph rings
//! alone. Sampling is sliding windows over the whole tokenized corpus,
//! since free text has no ring to rotate — `p4radice::rotate` stays
//! available for anyone doing pure-IMASM ring work, it is just not what
//! feeds training here anymore.
//!
//! Usage: p4-train [flags]

use candle_core::Tensor;
use candle_nn::{AdamW, Optimizer, ParamsAdamW, VarBuilder, VarMap};
use p4radice::{device, tok, Config, DialetheicLlm};
use rand::Rng;
use std::io::Read;

/// Every knob, on the command line. Hardcoding them means a sweep is a
/// rebuild, so no sweep ever gets run and the numbers that matter -- width,
/// depth, learning rate -- never get varied at all.
struct Args {
    corpus: String,
    tokenizer: String,
    out: String,
    steps: usize,
    lr: f64,
    gate_lambda: f64,
    batch: usize,
    seed: u64,
    log_every: usize,
    d_model: usize,
    n_head: usize,
    d_ff: usize,
    n_layer: usize,
    max_len: usize,
}

impl Default for Args {
    fn default() -> Self {
        Args {
            corpus: "/home/mrnob0dy666/imsgct/p4radice/corpus/combined.txt".into(),
            tokenizer: "/home/mrnob0dy666/imsgct/p4radice/tokenizer.json".into(),
            out: "/home/mrnob0dy666/imsgct/p4radice/p4radice.safetensors".into(),
            steps: 2000,
            lr: 3e-4,
            gate_lambda: 0.01,
            batch: 8,
            seed: 0x9E3779B97F4A7C15,
            log_every: 100,
            d_model: 64,
            n_head: 4,
            d_ff: 256,
            n_layer: 4,
            max_len: 128,
        }
    }
}

const USAGE: &str = "\
p4-train [flags]

  --corpus F        combined text corpus              (corpus/combined.txt)
  --tokenizer F     trained tokenizer.json             (tokenizer.json)
  --out F           checkpoint path                   (p4radice.safetensors)
  --steps n         training steps                    (2000)
  --lr F            AdamW learning rate                (3e-4)
  --gate-lambda F   weight on the mu∘delta=id penalty  (0.01)
  --batch n         windows per step                   (8)
  --seed n          RNG seed                          (0x9E3779B97F4A7C15)
  --log-every n     steps between log lines            (100)
  --d-model n       model width                        (64)
  --n-head n        attention heads                    (4)
  --d-ff n          feed-forward width                  (256)
  --n-layer n       depth                              (4)
  --max-len n       window length in tokens             (128)
  -h, --help        this
";

fn parse_args() -> Args {
    let mut a = Args::default();
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let mut i = 0usize;
    let val = |i: &mut usize, argv: &[String], name: &str| -> String {
        *i += 1;
        argv.get(*i).cloned().unwrap_or_else(|| {
            eprintln!("{name} wants a value");
            std::process::exit(2)
        })
    };
    while i < argv.len() {
        let t = argv[i].clone();
        match t.as_str() {
            "-h" | "--help" => {
                print!("{USAGE}");
                std::process::exit(0)
            }
            "--corpus" => a.corpus = val(&mut i, &argv, "--corpus"),
            "--tokenizer" => a.tokenizer = val(&mut i, &argv, "--tokenizer"),
            "--out" => a.out = val(&mut i, &argv, "--out"),
            "--steps" => a.steps = val(&mut i, &argv, "--steps").parse().expect("--steps"),
            "--lr" => a.lr = val(&mut i, &argv, "--lr").parse().expect("--lr"),
            "--gate-lambda" => {
                a.gate_lambda = val(&mut i, &argv, "--gate-lambda").parse().expect("--gate-lambda")
            }
            "--batch" => a.batch = val(&mut i, &argv, "--batch").parse().expect("--batch"),
            "--seed" => a.seed = val(&mut i, &argv, "--seed").parse().expect("--seed"),
            "--log-every" => {
                a.log_every = val(&mut i, &argv, "--log-every").parse().expect("--log-every")
            }
            "--d-model" => a.d_model = val(&mut i, &argv, "--d-model").parse().expect("--d-model"),
            "--n-head" => a.n_head = val(&mut i, &argv, "--n-head").parse().expect("--n-head"),
            "--d-ff" => a.d_ff = val(&mut i, &argv, "--d-ff").parse().expect("--d-ff"),
            "--n-layer" => a.n_layer = val(&mut i, &argv, "--n-layer").parse().expect("--n-layer"),
            "--max-len" => a.max_len = val(&mut i, &argv, "--max-len").parse().expect("--max-len"),
            other => {
                eprintln!("unknown flag {other}\n{USAGE}");
                std::process::exit(2)
            }
        }
        i += 1;
    }
    if a.d_model % a.n_head != 0 {
        eprintln!("--d-model ({}) must divide by --n-head ({})", a.d_model, a.n_head);
        std::process::exit(2)
    }
    a
}

fn main() -> anyhow::Result<()> {
    let a = parse_args();

    let tokenizer = tok::load(&a.tokenizer).map_err(|e| anyhow::anyhow!("{e}"))?;
    let vocab_size = tokenizer.get_vocab_size(true);

    let mut raw = String::new();
    std::fs::File::open(&a.corpus)?.read_to_string(&mut raw)?;
    let ids: Vec<u32> = tok::encode(&tokenizer, &raw).map_err(|e| anyhow::anyhow!("{e}"))?;
    if ids.len() < a.max_len + 1 {
        anyhow::bail!(
            "corpus tokenizes to {} tokens, need at least --max-len+1 ({})",
            ids.len(),
            a.max_len + 1
        );
    }
    println!(
        "[corpus] {} chars from {} -> {} tokens (vocab {}), tokenizer {}",
        raw.len(),
        a.corpus,
        ids.len(),
        vocab_size,
        a.tokenizer
    );

    let cfg = Config {
        vocab_size,
        d_model: a.d_model,
        n_head: a.n_head,
        d_ff: a.d_ff,
        n_layer: a.n_layer,
        max_len: a.max_len,
    };
    let dev = device()?;
    let varmap = VarMap::new();
    let vb = VarBuilder::from_varmap(&varmap, p4radice::dtype(), &dev);
    let model = DialetheicLlm::new(cfg, vb)?;

    let params = ParamsAdamW { lr: a.lr, ..Default::default() };
    let mut opt = AdamW::new(varmap.all_vars(), params)?;

    let mut rng = rand::rngs::StdRng::seed_from_u64(a.seed);
    use rand::SeedableRng;

    let window = a.max_len + 1; // +1 so input/target each get max_len tokens
    let mut prev_norm: Option<f64> = None;
    for step in 0..a.steps {
        let mut step_ce = 0f32;
        let mut step_gate = 0f32;
        let mut n_seen = 0usize;
        for _ in 0..a.batch {
            let start = rng.gen_range(0..ids.len() - window + 1);
            let slice = &ids[start..start + window];
            let n = slice.len();

            let input = Tensor::from_vec(slice[..n - 1].to_vec(), (1, n - 1), &dev)?;
            let target = Tensor::from_vec(slice[1..n].to_vec(), (1, n - 1), &dev)?;

            let logits = model.forward(&input)?; // (1, n-1, V)
            let logits = logits.reshape(((n - 1), vocab_size))?;
            let target = target.reshape((n - 1,))?;
            let ce = candle_nn::loss::cross_entropy(&logits, &target)?;
            let gate = model.gate_penalty()?;
            let loss = (&ce + (&gate * a.gate_lambda)?)?;

            opt.backward_step(&loss)?;
            step_ce += ce.to_scalar::<f32>()?;
            step_gate += gate.to_scalar::<f32>()?;
            n_seen += 1;
        }
        if n_seen == 0 {
            continue;
        }
        let avg_ce = step_ce / n_seen as f32;
        let avg_gate = step_gate / n_seen as f32;

        if step % a.log_every == 0 || step + 1 == a.steps {
            // ⊙ self-modeling: the update the model just made, read back off
            // its own weights, not asserted.
            let mut sq = 0f64;
            for v in varmap.all_vars() {
                let t = v.as_tensor().to_dtype(p4radice::dtype())?;
                let s: f64 = t.sqr()?.sum_all()?.to_scalar::<f32>()? as f64;
                sq += s;
            }
            let norm = sq.sqrt();
            let delta = prev_norm.map(|p| norm - p).unwrap_or(0.0);
            prev_norm = Some(norm);
            println!(
                "step {step:6} loss {avg_ce:.4} gate {avg_gate:.4}  |W|={norm:.4} d|W|={delta:+.4}"
            );
        }
    }

    varmap.save(&a.out)?;
    println!("[anchor] saved {}", a.out);
    Ok(())
}

