//! Trains a byte-level BPE tokenizer over the combined corpus -- ig-docs
//! prose, the ob3ect opcode rings, and their Shavian tuples together as one
//! vocabulary, not three. Byte-level so no character (a mark, a Shavian
//! letter, anything in ig-docs) is ever out-of-vocabulary; BPE so common
//! English substrings and common glyph runs both get single tokens instead
//! of the model paying one step per byte for everything.
//!
//! Plain byte-level BPE alone is not enough: a rare multi-byte character
//! (most of the Shavian block, most math/astrological symbols) may appear
//! too few times in 62MB of mostly-English text for its bytes to ever earn
//! a BPE merge, at any vocab size -- checked directly: doubling vocab_size
//! from 8000 to 16000 did not fix this, it went from 175 to 201 orphan
//! single-byte tokens (tokens that are not valid standalone UTF-8, so
//! sampling one alone at generation time prints a replacement character or
//! a split glyph). The fix is to guarantee every distinct character the
//! corpus actually contains gets its own atomic token, added directly
//! after BPE training rather than left to merge frequency.
use std::collections::HashSet;
use std::env;
use std::fs;
use tokenizers::models::bpe::BpeTrainerBuilder;
use tokenizers::normalizers::NFC;
use tokenizers::pre_tokenizers::byte_level::ByteLevel;
use tokenizers::tokenizer::{NormalizedString, Normalizer};
use tokenizers::{AddedToken, TokenizerBuilder};

fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let args: Vec<String> = env::args().collect();
    let corpus = args.get(1).cloned().unwrap_or_else(|| "corpus/combined.txt".into());
    let out = args.get(2).cloned().unwrap_or_else(|| "tokenizer.json".into());
    let vocab_size: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(8000);

    let mut tokenizer = TokenizerBuilder::new()
        .with_model(tokenizers::models::bpe::BPE::default())
        .with_normalizer(Some(NFC))
        .with_pre_tokenizer(Some(ByteLevel::default()))
        .with_post_processor(Some(ByteLevel::default()))
        .with_decoder(Some(ByteLevel::default()))
        .build()?;

    let mut trainer = BpeTrainerBuilder::new()
        .vocab_size(vocab_size)
        .min_frequency(2)
        .special_tokens(vec![AddedToken::from("<pad>", true), AddedToken::from("<bos>", true), AddedToken::from("<eos>", true)])
        .initial_alphabet(ByteLevel::alphabet().into_iter().collect())
        .build();

    tokenizer.train_from_files(&mut trainer, vec![corpus.clone()])?;

    // Build the added-token set from the NFC-NORMALIZED text, not raw text --
    // the tokenizer's own pipeline runs NFC before matching added vocabulary,
    // so a character the corpus spells one way but NFC folds into another
    // never matches an added token built from the raw spelling, and falls
    // through to byte-level BPE. Checked directly: with raw-text added
    // tokens, 112,455 of 19,884,542 corpus tokens (0.57%) still landed on
    // one of the orphan single-byte tokens despite this fix supposedly
    // covering every character.
    let raw_text = fs::read_to_string(&corpus)?;
    let mut normalized = NormalizedString::from(raw_text.as_str());
    NFC.normalize(&mut normalized)?;
    let non_ascii: HashSet<String> = normalized
        .get()
        .chars()
        .filter(|c| !c.is_ascii())
        .map(|c| c.to_string())
        .collect();
    // `special: false` -- these are real vocabulary, not control tokens like
    // <pad>/<bos>/<eos>. Passing true here silently dropped every mark and
    // Shavian character on decode (skip_special_tokens defaults to true),
    // caught by round-tripping a real mixed string before trusting this.
    let added: Vec<AddedToken> = non_ascii
        .into_iter()
        .map(|s| AddedToken::from(s, false))
        .collect();
    let n_added = tokenizer.add_tokens(&added);

    tokenizer.save(&out, false)?;
    println!(
        "[tokenizer] trained on {corpus}, vocab_size={vocab_size}, {n_added} atomic non-ASCII tokens added, saved to {out}"
    );
    Ok(())
}

