    let shift_normalizers: Vec<NormalizerWrapper> = shift_pairs
        .iter()
        .map(|(real, pua)| NormalizerWrapper::Replace(Replace::new(real.to_string(), pua.to_string()).unwrap()))
        .collect();
    let unshift_decoders: Vec<DecoderWrapper> = shift_pairs
        .iter()
        .map(|(real, pua)| DecoderWrapper::Replace(Replace::new(pua.to_string(), real.to_string()).unwrap()))
        .collect();

    let mut normalizer_chain = vec![NormalizerWrapper::NFC(NFC)];
    normalizer_chain.extend(shift_normalizers);

    let mut decoder_chain = unshift_decoders;
    decoder_chain.push(DecoderWrapper::ByteLevel(ByteLevel::default()));

    let mut tokenizer = TokenizerBuilder::new()
        .with_model(tokenizers::models::bpe::BPE::default())
        .with_normalizer(Some(NormalizerWrapper::Sequence(NormalizerSequence::new(normalizer_chain))))
        .with_pre_tokenizer(Some(ByteLevel::default()))
        .with_post_processor(Some(ByteLevel::default()))
        .with_decoder(Some(DecoderWrapper::Sequence(DecoderSequence::new(decoder_chain))))
        .build()?;

    let mut trainer = BpeTrainerBuilder::new()
        .vocab_size(vocab_size)
        .min_frequency(2)
        .special_tokens(vec![AddedToken::from("<pad>", true), AddedToken::from("<bos>", true), AddedToken::from("<eos>", true)])
        .initial_alphabet(ByteLevel::alphabet().into_iter().collect())
        .build();

