/// Every codepoint GPT-2's byte-level scheme reuses as a raw-byte
/// placeholder -- taken from `ByteLevel::alphabet()` itself (the library's
/// own authoritative table), not reconstructed by hand. Hand-reconstructing
/// it once already produced a real bug: it covered only the Latin-1
/// Supplement collision zone (0xA1..=0xFF) and missed that GPT-2 also
/// escapes its remaining non-printable bytes into Latin Extended-A
/// (roughly U+0100..=U+0143), which real corpus characters like Ħ, ħ, Ł,
/// ı, Ĥ, ī also collide with -- caught only by tracing actual leftover
/// orphan-token occurrences in the corpus after the first fix, not by
/// re-deriving the table again by inspection. Plain ASCII printables
/// (33..=126) map to themselves in that table too but never need shifting:
/// they are single-byte-safe already, and shifting them would corrupt
/// ordinary English text for no reason.
fn colliding_codepoints() -> Vec<u32> {
    ByteLevel::alphabet()
        .into_iter()
        .map(|c| c as u32)
        .filter(|&cp| !(0x21..=0x7E).contains(&cp))
        .collect()
}

const PUA_BASE: u32 = 0xE000;

fn build_shift_pairs() -> Vec<(char, char)> {
    let mut cps = colliding_codepoints();
    cps.sort_unstable();
    cps.dedup();
    cps.into_iter()
        .enumerate()
        .map(|(i, cp)| {
            let real = char::from_u32(cp).unwrap();
            let pua = char::from_u32(PUA_BASE + i as u32).unwrap();
            (real, pua)
        })
        .collect()
}

