//! Trains a byte-level BPE tokenizer over the combined corpus -- ig-docs
//! prose, the ob3ect opcode rings, and their Shavian tuples together as one
//! vocabulary, not three. Byte-level so no character (a mark, a Shavian
//! letter, anything in ig-docs) is ever out-of-vocabulary; BPE so common
//! English substrings and common glyph runs both get single tokens instead
//! of the model paying one step per byte for everything.
//!
//! Real corpus characters in U+00A1..=U+00FF (Latin-1 Supplement, minus the
//! soft hyphen U+00AD) COLLIDE with GPT-2's byte-level escape scheme: raw
//! bytes 0xA1..=0xFF get mapped to those exact same codepoints as printable
//! placeholders, so the vocabulary already contains a token whose surface
//! string is e.g. "¹" standing for the raw byte 0xB9 -- meaning adding the
//! real Unicode character U+00B9 as its own token is refused by
//! `add_tokens` ("only added if it doesn't already exist"), and the model
//! ends up emitting the byte-placeholder instead of the real character,
//! printing garbage or a split glyph. Traced to one real occurrence (φ⁻¹ in
//! a Pentagon-form matrix) before believing it: 112,455 of 19,884,542
//! corpus tokens (0.57%) landed on one of these 175 collision tokens.
//!
//! Fixed at the pipeline level, not by adding more tokens: every colliding
//! character is shifted to a private-use codepoint (U+E000 + offset)
//! BEFORE ByteLevel ever sees it, via a `Replace` normalizer chain baked
//! into the tokenizer itself -- so it never lands on the placeholder
//! codepoints at all, and the matching `Replace` DECODER chain (Replace
//! implements both traits) shifts it back on the way out. Round-trips
//! exactly, for any vocab size, with no separate wrapper needed outside
//! the tokenizer.
use std::collections::HashSet;
use std::env;
use std::fs;
use tokenizers::decoders::sequence::Sequence as DecoderSequence;
use tokenizers::models::bpe::BpeTrainerBuilder;
use tokenizers::normalizers::replace::Replace;
use tokenizers::normalizers::utils::Sequence as NormalizerSequence;
use tokenizers::normalizers::NFC;
use tokenizers::pre_tokenizers::byte_level::ByteLevel;
use tokenizers::tokenizer::{DecoderWrapper, NormalizedString, Normalizer, NormalizerWrapper};
use tokenizers::{AddedToken, TokenizerBuilder};

/// The Latin-1 Supplement codepoints GPT-2's byte-level scheme reuses as
/// raw-byte placeholders (0xA1..=0xAC, 0xAE..=0xFF -- 0xAD, soft hyphen, is
/// excluded from that placeholder set upstream, so it is not a collision).
fn colliding_codepoints() -> Vec<u32> {
    (0xA1..=0xAC).chain(0xAE..=0xFF).collect()
}

const PUA_BASE: u32 = 0xE000;

fn build_shift_pairs() -> Vec<(char, char)> {
    colliding_codepoints()
        .into_iter()
        .enumerate()
        .map(|(i, cp)| {
            let real = char::from_u32(cp).unwrap();
            let pua = char::from_u32(PUA_BASE + i as u32).unwrap();
            (real, pua)
        })
        .collect()
}

fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let args: Vec<String> = env::args().collect();
    let corpus = args.get(1).cloned().unwrap_or_else(|| "corpus/combined.txt".into());
    let out = args.get(2).cloned().unwrap_or_else(|| "tokenizer.json".into());
    let vocab_size: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(8000);

    let shift_pairs = build_shift_pairs();
    let shift_normalizers: Vec<NormalizerWrapper> = shift_pairs
        .iter()
        .map(|(real, pua)| NormalizerWrapper::Replace(Replace::new(real.to_string(), pua.to_string()).unwrap()))
        .collect();
    let unshift_decoders: Vec<DecoderWrapper> = shift_pairs
        .iter()
        .map(|(real, pua)| DecoderWrapper::Replace(Replace::new(pua.to_string(), real.to_string()).unwrap()))
        .collect();

    let mut normalizer_chain = vec![NormalizerWrapper::NFC(NFC)];
    normalizer_chain.extend(shift_normalizers);

    // ByteLevel MUST decode first: real Latin-1 characters (e.g. '¹') sit at
    // the exact same codepoints ByteLevel treats as its own raw-byte escape
    // alphabet, so un-shifting PUA -> real before ByteLevel runs means
    // ByteLevel immediately re-corrupts the just-restored character back
    // into a raw byte, producing a replacement character. Verified directly
    // both orderings before trusting this: unshift-then-ByteLevel round-
    // trips '¹' to '�'; ByteLevel-then-unshift round-trips it correctly.
    let mut decoder_chain = vec![DecoderWrapper::ByteLevel(ByteLevel::default())];
    decoder_chain.extend(unshift_decoders);

    let mut tokenizer = TokenizerBuilder::new()
        .with_model(tokenizers::models::bpe::BPE::default())
        .with_normalizer(Some(NormalizerWrapper::Sequence(NormalizerSequence::new(normalizer_chain))))
        .with_pre_tokenizer(Some(ByteLevel::default()))
        .with_post_processor(Some(ByteLevel::default()))
        .with_decoder(Some(DecoderWrapper::Sequence(DecoderSequence::new(decoder_chain))))
        .build()?;

    let mut trainer = BpeTrainerBuilder::new()
        .vocab_size(vocab_size)
        .min_frequency(2)
        .special_tokens(vec![AddedToken::from("<pad>", true), AddedToken::from("<bos>", true), AddedToken::from("<eos>", true)])
        .initial_alphabet(ByteLevel::alphabet().into_iter().collect())
        .build();

    tokenizer.train_from_files(&mut trainer, vec![corpus.clone()])?;

    // Added-token set built by running the SAME normalizer pipeline the
    // tokenizer will actually apply (NFC + the collision shift), so what we
    // add matches exactly what encode() will see -- not the raw corpus text.
    let raw_text = fs::read_to_string(&corpus)?;
    let mut normalized = NormalizedString::from(raw_text.as_str());
    for n in [NormalizerWrapper::NFC(NFC)]
        .into_iter()
        .chain(shift_pairs.iter().map(|(real, pua)| {
            NormalizerWrapper::Replace(Replace::new(real.to_string(), pua.to_string()).unwrap())
        }))
    {
        n.normalize(&mut normalized)?;
    }
    let non_ascii: HashSet<String> = normalized
        .get()
        .chars()
        .filter(|c| !c.is_ascii())
        .map(|c| c.to_string())
        .collect();
    // `special: false` -- these are real vocabulary, not control tokens like
    // <pad>/<bos>/<eos>. Passing true here silently dropped every mark and
    // Shavian character on decode (skip_special_tokens defaults to true),
    // caught by round-tripping a real mixed string before trusting this.
    let added: Vec<AddedToken> = non_ascii
        .into_iter()
        .map(|s| AddedToken::from(s, false))
        .collect();
    let n_added = tokenizer.add_tokens(&added);

    tokenizer.save(&out, false)?;
    println!(
        "[tokenizer] trained on {corpus}, vocab_size={vocab_size}, {n_added} atomic non-ASCII tokens added, {} collision codepoints shifted, saved to {out}",
        shift_pairs.len()
    );
    Ok(())
}

