@staticmethod
def _resolve_under(path_str: str, root: Path) -> Path:
    """Resolve path_str and require it to land under root, following
    symlinks -- raises ValueError otherwise. Blocks '..' escapes and
    symlink escapes alike, since resolve() follows both to their real
    target before the containment check runs."""
    candidate = Path(path_str).expanduser()
    if not candidate.is_absolute():
        candidate = root / candidate
    resolved = candidate.resolve()
    root_resolved = root.resolve()
    if root_resolved != resolved and root_resolved not in resolved.parents:
        raise ValueError(f"{resolved} is outside {root_resolved}")
    return resolved

def _handle_read_file(self, path_str: str) -> str:
    if not path_str:
        return "read_file: (empty path)"
    try:
        p = self._resolve_under(path_str, _IMSGCT_ROOT)
    except ValueError as e:
        return f"read_file: refused -- {e}"
    if not p.exists():
        return f"read_file: {p} does not exist"
    if not p.is_file():
        return f"read_file: {p} is not a regular file"
    try:
        content = p.read_text(errors="replace")
    except Exception as e:
        return f"read_file: error reading {p}: {e}"
    cap = 50000
    body = content[:cap]
    if len(content) > cap:
        body += f"\n[...truncated, {len(content) - cap} more chars not shown...]"
    return f"read_file: {p} ({len(content)} chars)\n{body}"

def _handle_write_file(self, path_str: str, content: str) -> str:
    if not path_str:
        return "write_file: (empty path)"
    try:
        p = self._resolve_under(path_str, _P4RAKERNEL_ROOT)
    except ValueError as e:
        return f"write_file: refused -- {e}"
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content)
    except Exception as e:
        return f"write_file: error writing {p}: {e}"
    return f"write_file: wrote {len(content)} chars to {p}"

