def tuple_algebra_main(args):
    """CLI driver: dispatch on the alg_args dict assembled by cli.py run_algebra."""
    lines = []
    t = args.get("tuple")
    if args.get("winding"):
        r = winding(of=args.get("winding_of"), turns=args.get("turns"),
                    angle=args.get("angle"), power=args.get("power"))
        out = (f"winding {r['winding']}  turns {r['turns']}  "
               f"radians {r['radians']:.6f}  closes_after {r['closes_after']}  "
               f"is_real {r['is_real']}")
        return json.dumps(r) if args.get("json") else out
    if not t:
        return ("usage: m3 algebra --tuple ⟨12 glyphs⟩ "
                "[--report|--decode|--distance X|--meet X|--join X|--winding ...]")
    try:
        parsed = _parse(t)
        if args.get("decode"):
            for s in SLOTS:
                lines.append(f"  {s}: {parsed[s]}")
        if args.get("report"):
            lines.append(f"tuple        {_clean(t)}")
            lines.append(f"tier         {tier(t)}")
            lines.append(f"consciousness {consciousness(t)}")
            refs = (args.get("compare_with") or "grammar,clink,aafa,psfoa").split(",")
            for ref in refs:
                ref = ref.strip()
                if ref in REFS:
                    lines.append(f"distance to {ref:<10} {distance(t, REFS[ref]):.4f}")
                else:
                    try:
                        lines.append(f"distance to {ref:<10} {distance(t, ref):.4f}")
                    except ValueError:
                        lines.append(f"distance to {ref:<10} (no reference tuple)")
        if args.get("distance"):
            ref = args["distance"]
            if ref in REFS:
                lines.append(f"distance to {ref}: {distance(t, REFS[ref]):.4f}")
            else:
                lines.append(f"distance to {ref}: {distance(t, ref):.4f}")
        if args.get("meet"):
            lines.append(f"meet: {meet(t, args['meet'])}")
        if args.get("join"):
            lines.append(f"join: {join(t, args['join'])}")
        if not lines:
            lines.append(_clean(t))
        return "\n".join(lines)
    except ValueError as e:
        return f"ERROR: {e}"

#!/usr/bin/env python3
"""ig_harness/momos.py — mOMonadOS-tool bridge.

Runs REPL commands against the hosted mOMonadOS kernel binary and returns the
real output. This is the mOMonadOS-tool focus of IG_HARNESS: an `MTOOL:` line
in the breath is executed against the live kernel, not narrated.

The hosted binary is the x86_64-linux-gnu build of the bare-metal kernel
(mOMonadOS/run_hosted.sh). It prints a `⊙>` prompt and accepts REPL commands
(ig, cycle, weight, banked, insert, trans, arev, decode, frob, d12, fibqc,
spine, vessel, ...) on stdin. We pipe commands + `quit` and parse output up to
the next prompt.

Author: Lando⊗⊙perator
"""
from __future__ import annotations

import os
import re
import shlex
import subprocess
from typing import Dict, List, Optional

# Hosted kernel binary locations, tried in order.
_MOMONADOS_BIN_CANDIDATES = [
    os.environ.get("MOMONADOS_BIN"),
    os.path.expanduser("/home/mrnob0dy666/imsgct/mOMonadOS/target/x86_64-unknown-linux-gnu/release/momonados"),
    os.path.expanduser("/home/mrnob0dy666/imsgct/mOMonadOS/target/x86_64-unknown-linux-gnu/debug/momonados"),
]

_ANSI_RE = re.compile(r"\x1b\[[0-9;]*m")

# Commands that are allowed through the bridge. Anything else is refused: the
# kernel owns its REPL, and the bridge must not become an arbitrary shell.
_ALLOWED_GROUPS = {
    # Grammar / catalog
    "ig", "classify", "frob", "aleph", "shor", "rh", "ym",
    # IMASM word walks
    "cycle", "weight", "banked", "insert", "trans", "arev",
    # Crystal FS
    "decode", "store", "find", "name",
    # Kernel utilities
    "spine", "vessel", "vita", "whoami", "ruleset",
    # Quantum / SIC
    "fibqc", "jones", "braids", "qft", "iuft", "sic", "d12", "d2048",
    # Status / programs
    "status", "snapshot", "program", "list", "canonical", "registers",
    # Rebis / dialect / cr3echrz
    "codon", "translate", "genetics", "materials", "bio", "tx",
    "dialect", "seal", "paraasm", "cr3", "p4ra", "help",
}

# Some REPL commands are one-word toggles — they take no args.
_ONE_WORD = {"arev", "whoami", "ruleset", "registers", "snapshot"}


def binary_path() -> Optional[str]:
    """First existing hosted binary, or None."""
    for cand in _MOMONADOS_BIN_CANDIDATES:
        if cand and os.path.isfile(cand):
            return cand
    return None


def available() -> bool:
    """True iff the hosted mOMonadOS binary exists on disk."""
    return binary_path() is not None


def _parse_repl_output(raw: str, cmd: str) -> str:
    """Extract the output segment for `cmd` from the raw REPL transcript.

    The kernel echoes each command after its prompt (`⊙> <cmd>`), runs it, and
    prints a fresh prompt. The boot banner may precede the first prompt. We
    locate the echoed command line and take every following line up to the
    next line that begins with a prompt (the `quit` prompt that closes the
    pipe).
    """
    text = _ANSI_RE.sub("", raw or "")
    lines = text.splitlines()
    echo = f"⊙> {cmd.strip()}"
    start = None
    for i, ln in enumerate(lines):
        if ln.rstrip() == echo or ln.startswith(echo + " "):
            start = i
            break
    if start is None:
        # no echo found — fall back to the tail after the last standalone prompt
        for i in range(len(lines) - 1, -1, -1):
            if lines[i].startswith("⊙>"):
                return "\n".join(lines[i + 1:]).strip()
        return text.strip()
    out = []
    for ln in lines[start + 1:]:
        if ln.startswith("⊙>") or ln.startswith("Halting") or ln.startswith("[SHUTDOWN]"):
            break
        out.append(ln)
    return "\n".join(out).strip()


def run(line: str, timeout: float = 60.0) -> Dict:
    """Run one `MTOOL:` line against the hosted kernel.

    Args:
        line: the command line after the `MTOOL:` prefix, e.g. "ig mOMonadOS"
              or "cycle ⊢⊙∈⊤⊥∋⋈◻⊣".
    Returns:
        {"status": "ok"|"refused"|"error"|"unavailable", "output": str, ...}
    """
    if not available():
        return {"status": "unavailable",
                "output": "mOMonadOS hosted binary not found (build with "
                          "mOMonadOS/run_hosted.sh)"}
    try:
        parts = shlex.split(line)
    except ValueError as exc:
        return {"status": "error", "output": f"cannot parse MTOOL line: {exc}"}
    if not parts:
        return {"status": "error", "output": "empty MTOOL line"}
    verb = parts[0].lower()
    if verb not in _ALLOWED_GROUPS:
        return {"status": "refused",
                "output": f"verb '{verb}' not in the mOMonadOS-tool allowlist "
                          f"({len(_ALLOWED_GROUPS)} verbs)"}
    if verb in _ONE_WORD and len(parts) > 1:
        return {"status": "refused",
                "output": f"'{verb}' takes no arguments"}
    if verb == "help" and len(parts) == 1:
        return {"status": "ok", "output": "(help menu available: "
                                          "MTOOL: help <topic>)"}

    cmd = line.strip()
    binp = binary_path()
    try:
        proc = subprocess.run(
            [binp],
            input=f"{cmd}\nquit\n",
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        return {"status": "error", "output": f"MTOOL timeout after {timeout}s"}
    except OSError as exc:
        return {"status": "error", "output": f"MTOOL spawn error: {exc}"}

    out = _parse_repl_output(proc.stdout or "", cmd)
    if not out:
        out = f"(no output; exit={proc.returncode})"
    return {"status": "ok", "output": out, "returncode": proc.returncode}


def quick_test() -> str:
    """Sanity check used by --check-momos: run `ig mOMonadOS`."""
    r = run("ig mOMonadOS")
    return f"binary={'yes' if available() else 'no'}\n" \
           f"status={r['status']}\noutput={r['output'][:400]}"

